insert into public.questions
  (section, topic, difficulty, body, options, correct_idx, explanation, time_limit_s, template, variant, code)
values
  ('coding', 'Recursion', 2, 'What does this code print?', array['21', '20', '3', '4'], 1, 'Each call takes the last digit (n % 10) and recurses on the rest (n / 10), so f adds the digits of 8813: 20.', 50, 'coding-digits-rec', '68d3cbf68767edb4', '{"c":"int f(int n) {\n  if (n == 0) return 0;\n  return n % 10 + f(n / 10);\n}\n\nprintf(\"%d \", f(8813));","cpp":"int f(int n) {\n  if (n == 0) return 0;\n  return n % 10 + f(n / 10);\n}\n\ncout << f(8813) << \" \";","java":"static int f(int n) {\n  if (n == 0) return 0;\n  return n % 10 + f(n / 10);\n}\n\nSystem.out.print(f(8813) + \" \");","python":"def f(n):\n    if n == 0:\n        return 0\n    return n % 10 + f(n // 10)\n\nprint(f(8813), end=\" \")","pseudo":"// \"/\" is integer division: 7 / 2 = 3\n\nfunction f(n)\n  if (n == 0)\n    return 0\n  end if\n  return n mod 10 + f(n / 10)\nend function\n\nprint f(8813)"}'::jsonb),
